values.value:
{
    "hdg_mms_structure": [
        {
            "apiName": "seg1_pole_grid",
            "type": "column-repeater",
            "countApiName": "s1_no_of_items",
            "maxColumns": 10,
            "fields": [
                {
                    "apiName": "s1_material",
                    "label": "MATERIAL",
                    "type": "picklist",
                    "required": true,
                    "options": [
                        "HDG MMS/Carport Structure",
                        "Piers for Tracker",
                        "RSJ"
                    ],
                    "defaultValue": "HDG MMS/Carport Structure"
                },
                {
                    "apiName": "s1_material_grade",
                    "label": "MATERIAL GRADE",
                    "type": "picklist",
                    "required": true,
                    "options": [
                        "E250",
                        "E350",
                        "E350.",
                        "Special Grade",
                        "E250."
                    ],
                    "controllingField": "s1_material",
                    "dependentOptionsMap": {
                        "HDG MMS/Carport Structure": [
                            "E250",
                            "E350"
                        ],
                        "Black Metal": [
                            "E250",
                            "E350"
                        ],
                        "Galvalume": [
                            "AZ150 GSM (350 MPA)",
                            "AZ200 GSM (550 MPA)"
                        ],
                        "Piers for Tracker": [
                            "E350.",
                            "Special Grade"
                        ],
                        "RSJ": [
                            "E250."
                        ]
                    }
                },
                {
                    "apiName": "s1_steel_rate",
                    "label": "STEEL RATE",
                    "type": "number",
                    "readOnly": true,
                    "formula": "(s1_material_grade=='E350')?61000:(s1_material_grade=='E250')?58000:(s1_material_grade=='AZ150 GSM (350 MPA)')?78000:(s1_material_grade=='AZ200 GSM (550 MPA)')?81000:(s1_material_grade=='E350.')?60000:(s1_material_grade=='Special Grade')?63000:(s1_material_grade=='E250.')?52000:0"
                },
                {
                    "apiName": "s1_materialDesc",
                    "label": "MATERIAL DESCRIPTION",
                    "type": "number",
                    "unit": "MM"
                },
                {
                    "apiName": "s1_thickness",
                    "label": "THICKNESS",
                    "type": "picklist",
                    "unit": "MM",
                    "defaultValue": "",
                    "options": [
                        "2",
                        "2.5",
                        "3",
                        "5"
                    ],
                    "controllingField": "s1_material_grade",
                    "dependentOptionsMap": {
                        "E250": [
                            "2",
                            "2.5",
                            "3"
                        ],
                        "E350": [
                            "2",
                            "2.5",
                            "3"
                        ],
                        "E350.": [
                            "5"
                        ],
                        "Special Grade": [
                            "5"
                        ]
                    }
                },
                {
                    "apiName": "s1_micron_thickness",
                    "label": "MICRON THICKNESS",
                    "type": "picklist",
                    "unit": "µm",
                    "defaultValue": "",
                    "options": [
                        "60",
                        "70",
                        "80",
                        "90",
                        "100",
                        "110"
                    ]
                },
                {
                    "apiName": "s1_zincper_zincper",
                    "label": "ZINC %",
                    "type": "number",
                    "unit": "%",
                    "readOnly": true,
                    "formula": "(s1_material=='RSJ')?'4.5':((s1_thickness==2)?((((255/s1_thickness)*(7.093*s1_micron_thickness)/1000000*1.105757)*100).toFixed(2)):((s1_material=='Piers for Tracker')?'5':((((255/s1_thickness)*(7.093*s1_micron_thickness)/1000000*1.303)*100).toFixed(2))))"
                },
                {
                    "apiName": "s1_total_weight",
                    "label": "TOTAL WEIGHT (MT)",
                    "type": "number",
                    "unit": "mt",
                    "required": true
                },
                {
                    "apiName": "s1_freight",
                    "label": "FREIGHT",
                    "type": "number"
                },
                {
                    "apiName": "s1_quote_value",
                    "label": "QUOTE VALUE",
                    "type": "number",
                    "formula": "(s1_material_grade=='E250'?(((s1_steel_rate*(s1_material=='Piers for Tracker'?1.01:1.005))+(2000+(340000*(s1_zincper_zincper/100)*1.05))+(2000+1000+s1_freight)+(1500+(s1_thickness==2?0:500))+2500)-(s1_discount!=null?s1_discount:0)-3000):(((s1_steel_rate*(s1_material=='Piers for Tracker'?1.01:1.005))+(2000+(340000*(s1_zincper_zincper/100)*1.05))+(2000+1000+s1_freight)+(1500+(s1_thickness==2?0:500))+2500)-(s1_discount!=null?s1_discount:0)))",
                    "readOnly": true
                },
                {
                    "apiName": "s1_discount",
                    "label": "DISCOUNT",
                    "type": "number"
                },
                {
                    "apiName": "s1_quantity",
                    "label": "QUANTITY",
                    "type": "number"
                }
            ]
        }
    ],
    "lp_s1_foundation": [
        {
            "apiName": "seg1_foundation_grid",
            "type": "column-repeater",
            "countApiName": "s1_no_of_items",
            "maxColumns": 10,
            "fields": [
                {
                    "apiName": "s2_material",
                    "label": "MATERIAL",
                    "type": "picklist",
                    "required": true,
                    "options": [
                        "Black Metal",
                        "Galvalume"
                    ]
                },
                {
                    "apiName": "s2_material_grade",
                    "label": "GRADE",
                    "type": "picklist",
                    "required": true,
                    "options": [
                        "E250",
                        "E350",
                        "AZ150 GSM (350 MPA)",
                        "AZ200 GSM (550 MPA)"
                    ],
                    "controllingField": "s2_material",
                    "dependentOptionsMap": {
                        "Black Metal": [
                            "E250",
                            "E350"
                        ],
                        "Galvalume": [
                            "AZ150 GSM (350 MPA)",
                            "AZ200 GSM (550 MPA)"
                        ]
                    }
                },
                {
                    "apiName": "s2_steel_rate",
                    "label": "STEEL RATE",
                    "type": "number",
                    "readOnly": true,
                    "formula": "(s2_material_grade=='E350')?61000:(s2_material_grade=='E250')?58000:(s2_material_grade=='AZ150 GSM (350 MPA)')?78000:(s2_material_grade=='AZ200 GSM (550 MPA)')?81000:(s2_material_grade=='E350.')?60000:(s2_material_grade=='Special Grade')?63000:(s2_material_grade=='E250.')?52000:0"
                },
                {
                    "apiName": "s2_materialDesc",
                    "label": "MATERIAL DESCRIPTION",
                    "type": "number",
                    "uni": "mm"
                },
                {
                    "apiName": "s2_thickness",
                    "label": "THICKNESS",
                    "type": "picklist",
                    "defaultValue": "",
                    "options": [
                        "0.9",
                        "1.0",
                        "1.2",
                        "1.5",
                        "1.6",
                        "2.0",
                        "2",
                        "2.5",
                        "3"
                    ]
                },
                {
                    "apiName": "s2_unit_weight",
                    "label": "UNIT WEIGHT (MT)",
                    "type": "number",
                    "unit": "MT"
                },
                {
                    "apiName": "s2_total_weight",
                    "label": "TOTAL WEIGHT (MT)",
                    "type": "number",
                    "unit": "mt"
                },
                {
                    "apiName": "s2_freight",
                    "label": "FREIGHT",
                    "type": "number"
                },
                {
                    "apiName": "s2_quote_value",
                    "label": "QUOTE VALUE",
                    "type": "number",
                    "formula": "(((s2_steel_rate*1.005)+(3000+s2_freight)+(1000+500+(s2_material=='Black Metal'?500:0))+2500)+((s2_material!='Black Metal'&&s2_thickness>1.1)?3000:0))",
                    "readOnly": true
                },
                {
                    "apiName": "s1_discount",
                    "label": "DISCOUNT",
                    "type": "number"
                }
            ]
        }
    ]
}
